cd /tmp && cat > /tmp/gate-check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g2-2/bot.mjs';

const base = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
// Tokyo is UTC+9 with no DST. Builds a Date from a local Tokyo wall time.
const tokyo = (iso) => new Date(`${iso}+09:00`);

// Quiet window 22:00-07:00 wraps midnight: start included, end excluded.
let g = createPushGate();
assert.deepEqual(g.attempt(base, tokyo('2026-10-22T21:59:00')), { allowed: true, reason: null });
g = createPushGate();
assert.equal(g.attempt(base, tokyo('2026-10-22T22:00:00')).reason, 'quiet_hours');
assert.equal(g.attempt(base, tokyo('2026-10-23T00:30:00')).reason, 'quiet_hours');
assert.equal(g.attempt(base, tokyo('2026-10-23T06:59:00')).reason, 'quiet_hours');
assert.deepEqual(g.attempt(base, tokyo('2026-10-23T07:00:00')), { allowed: true, reason: null });

// Quiet refusals do not use up the cap. Cap 3 gives exactly 3 allowed, then daily_cap_reached.
g = createPushGate();
const day = { ...base, quietStart: '22:00', quietEnd: '07:00' };
for (let i = 0; i < 2; i++) assert.equal(g.attempt(day, tokyo('2026-10-22T23:00:00')).reason, 'quiet_hours');
assert.equal(g.attempt(day, tokyo('2026-10-22T12:00:00')).allowed, true);
assert.equal(g.attempt(day, tokyo('2026-10-22T13:00:00')).allowed, true);
assert.equal(g.attempt(day, tokyo('2026-10-22T14:00:00')).allowed, true);
assert.equal(g.attempt(day, tokyo('2026-10-22T15:00:00')).reason, 'daily_cap_reached');

// Local day rolls over at local midnight: the cap resets on the next local date.
assert.equal(g.attempt(day, tokyo('2026-10-23T08:00:00')).allowed, true);

// Same instant, different zones, different local day. 2026-10-22T08:00 Tokyo = 2026-10-21T19:00 New York.
g = createPushGate();
const ny = { ...base, id: 'u_ny', timeZone: 'America/New_York', quietStart: '22:00', quietEnd: '07:00', dailyCap: 1 };
const nowTokyo = tokyo('2026-10-22T08:00:00');
assert.equal(g.attempt(base, nowTokyo).allowed, true);
assert.equal(g.attempt(base, nowTokyo).reason, 'daily_cap_reached');
assert.equal(g.attempt(ny, nowTokyo).allowed, true);   // NY day is 2026-10-21; separate user anyway
assert.equal(g.attempt(ny, nowTokyo).reason, 'daily_cap_reached');

// Two gates are independent.
assert.equal(createPushGate().attempt(base, tokyo('2026-10-22T12:00:00')).allowed, true);

// DST: New York falls back 2026-11-01 at 02:00 EDT. 06:30 EST is still in the 22:00-07:00 quiet window.
g = createPushGate();
const nyDst = { ...ny, dailyCap: 5 };
assert.equal(g.attempt(nyDst, new Date('2026-11-01T11:30:00Z')).reason, 'quiet_hours'); // 06:30 EST
assert.equal(g.attempt(nyDst, new Date('2026-11-01T12:30:00Z')).allowed, true);         // 07:30 EST

// Cap 0 blocks every push in the day.
assert.equal(createPushGate().attempt({ ...base, dailyCap: 0 }, tokyo('2026-10-22T12:00:00')).reason, 'daily_cap_reached');

// Distinct codes for each rule, and bad input is held with its own code.
const ok = tokyo('2026-10-22T12:00:00');
const codes = {
  invalid_user: createPushGate().attempt({ ...base, id: '' }, ok).reason,
  invalid_time: createPushGate().attempt(base, new Date('nope')).reason,
  invalid_time_zone: createPushGate().attempt({ ...base, timeZone: 'Mars/Olympus' }, ok).reason,
  invalid_quiet_hours: createPushGate().attempt({ ...base, quietStart: '25:00' }, ok).reason,
  invalid_daily_cap: createPushGate().attempt({ ...base, dailyCap: -1 }, ok).reason,
};
assert.deepEqual(codes, {
  invalid_user: 'invalid_user',
  invalid_time: 'invalid_time',
  invalid_time_zone: 'invalid_time_zone',
  invalid_quiet_hours: 'invalid_quiet_hours',
  invalid_daily_cap: 'invalid_daily_cap',
});
assert.equal(new Set(['quiet_hours', 'daily_cap_reached', ...Object.values(codes)]).size, 7);

// Many calls for one user don't grow the history beyond today and yesterday.
g = createPushGate();
const many = { ...base, quietStart: '23:00', quietEnd: '23:00', dailyCap: 1000 };
for (let d = 1; d <= 20; d++) g.attempt(many, new Date(Date.UTC(2026, 9, d, 3, 0)));
console.log('all checks passed');
EOF
